import{_ as d,c as a,o,b0 as r}from"./chunks/framework.C5ev1SXp.js";const p=JSON.parse('{"title":"LV014-指令集与流水线","description":null,"frontmatter":{"title":"LV014-指令集与流水线","date":"2026-10-16T08:11:59.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/basic/computer-and-mcu/126d62aa93073c6745351be7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-16T08:11:59.966Z","fulluuid":"745351be78fb4da891960d5ecbf4fb77","useduuid":"745351be7"}},"headers":[],"relativePath":"sdoc/basic/computer-and-mcu/126d62aa93073c6745351be7.md","filePath":"sdoc/10-基础篇/02-计算机与单片机基础/LV014-指令集与流水线.md","lastUpdated":1792035518000}'),e={name:"sdoc/basic/computer-and-mcu/126d62aa93073c6745351be7.md"};function s(n,t,c,i,h,l){return o(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="lv014-指令集与流水线" tabindex="-1">LV014-指令集与流水线 <a class="header-anchor" href="#lv014-指令集与流水线" aria-label="Permalink to &quot;LV014-指令集与流水线&quot;">​</a></h1><p>上一篇把芯片的架构骨架看完了——内核、总线、存储器、外设各就各位。这一篇钻进<strong>内核内部</strong>，回答两个决定 CPU&quot;语言&quot;和&quot;节奏&quot;的问题：<strong>CPU 认识哪些指令（指令集）？它怎么把这些指令执行得又快又稳（流水线）？</strong></p><p>这两个话题不是纯理论：读懂反汇编、评估一段代码为什么快或慢、理解中断响应的周期数，都要用到它们。本篇的阅读主线：指令集是软硬件之间的契约 → 契约有两种风格（CISC/RISC）→ ARM 选择的 Thumb-2 → 执行指令的装配线（五段流水线）→ 装配线上的三类障碍 → 深浅流水线的取舍 → 落到写代码的实际启示。</p><h2 id="一、-指令集-cpu-与程序之间的契约" tabindex="-1">一、 指令集：CPU 与程序之间的契约 <a class="header-anchor" href="#一、-指令集-cpu-与程序之间的契约" aria-label="Permalink to &quot;一、 指令集：CPU 与程序之间的契约&quot;">​</a></h2><h3 id="_1-什么是指令集" tabindex="-1">1. 什么是指令集 <a class="header-anchor" href="#_1-什么是指令集" aria-label="Permalink to &quot;1. 什么是指令集&quot;">​</a></h3><p>指令集架构 ISA（Instruction Set Architecture）是一台 CPU 能识别的<strong>全部指令</strong>，加上<strong>寄存器模型</strong>（有哪些寄存器可用）、<strong>寻址方式</strong>（操作数怎么找到）和<strong>异常模型</strong>（中断怎么响应）的完整规约。</p><p>它的本质是<strong>软硬件之间的接口契约</strong>：向上，编译器按它把 C 代码翻译成机器码；向下，电路设计者按它实现芯片行为。两边只认契约、互不越界——所以同一份程序能在任何实现相同 ISA 的芯片上运行，同一个 ISA 可以被不同厂商做出性能迥异的芯片。</p><p>指令本身由<strong>操作码 + 操作数</strong>组成（<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 讲过&quot;操作码 + 地址码&quot;），例如一条 ARM 加法指令：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ADDS  R0, R1, R2    ; R0 = R1 + R2，并更新标志位</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>【<strong>注意</strong>】</p><p>区分两个常被混用的词：<strong>ISA 是&quot;说什么&quot;</strong>（指令集合、寄存器模型），<strong>微架构是&quot;怎么说&quot;</strong>（流水线级数、缓存大小、分支预测器）。Cortex-M3 和 Cortex-M4 实现同一代 ISA（ARMv7-M，M4 增加的 DSP/FPU 扩展记为 ARMv7E-M），但微架构不同、性能不同——而流水线正属于微架构，这是第二部分的主角。</p><h3 id="_2-cisc-与-risc-两种设计哲学" tabindex="-1">2. CISC 与 RISC：两种设计哲学 <a class="header-anchor" href="#_2-cisc-与-risc-两种设计哲学" aria-label="Permalink to &quot;2. CISC 与 RISC：两种设计哲学&quot;">​</a></h3><p>指令集怎么设计，历史上有两条路线，理念几乎相反：</p><p>（1）<strong>CISC（Complex Instruction Set，复杂指令集）</strong>：诞生于内存昂贵、编译器简陋的年代——让一条指令干尽量多的事（一条指令直接操作内存完成&quot;取数 + 运算 + 存回&quot;），用复杂指令压缩程序体积、减少访存。指令数量多、长度可变、执行周期数不一，代表是 x86；</p><p>（2）<strong>RISC（Reduced Instruction Set，精简指令集）</strong>：源于一个统计发现——程序 80% 的时间在执行 20% 的简单指令。于是反过来：只保留最常用的简单指令，<strong>定长编码</strong>、<strong>大多数指令单周期完成</strong>、<strong>只有取数/存数指令能访问内存</strong>（Load/Store 架构，运算只在寄存器之间进行）。规整的指令让硬件简单、流水线高效，代表是 ARM、RISC-V、MIPS。</p><table tabindex="0"><thead><tr><th>维度</th><th>CISC</th><th>RISC</th></tr></thead><tbody><tr><td>指令数量</td><td>多（几百到上千条）</td><td>少（几十到百余条）</td></tr><tr><td>指令长度</td><td>可变（x86 从 1 到 15 字节）</td><td>定长为主（ARM Thumb-2 为 16/32 位混合）</td></tr><tr><td>访存方式</td><td>运算指令可直接操作内存</td><td>仅 Load/Store 指令访存</td></tr><tr><td>单条执行周期</td><td>多周期不等</td><td>大多单周期</td></tr><tr><td>设计重心</td><td>压缩代码体积</td><td>面向流水线与编译器优化</td></tr><tr><td>代表</td><td>x86</td><td>ARM、RISC-V、MIPS</td></tr></tbody></table><p>两条路线今天已经<strong>趋同</strong>：现代 x86 CPU 内部会把复杂的 CISC 指令拆成类 RISC 的微操作再乱序执行（CISC 的壳、RISC 的芯）；而 ARM 也在 RISC 底子上不断加回复杂指令（DSP 指令、浮点指令）。所以不必站队记教条，理解各自&quot;为什么这样设计&quot;即可——<strong>ARM 属于 RISC 阵营</strong>，它的 Load/Store 特性马上会在下面看到。</p><h3 id="_3-arm-的指令集演进-arm-→-thumb-→-thumb-2" tabindex="-1">3. ARM 的指令集演进：ARM → Thumb → Thumb-2 <a class="header-anchor" href="#_3-arm-的指令集演进-arm-→-thumb-→-thumb-2" aria-label="Permalink to &quot;3. ARM 的指令集演进：ARM → Thumb → Thumb-2&quot;">​</a></h3><p>ARM 自己的 ISA 也经历了一次&quot;密度与性能&quot;的权衡，值得一看：</p><p>（1）<strong>ARM 指令集（A32）</strong>：32 位定长指令，功能完整、性能好，但每条指令固定占 4 字节，程序体积大——对 FLASH 只有几十 KB 的单片机很奢侈；</p><p>（2）<strong>Thumb 指令集（T16）</strong>：把最常用的指令压缩成 16 位编码，代码密度接近翻倍，代价是功能只是 ARM 的子集（寄存器访问受限、无条件执行等），性能略降；</p><p>（3）<strong>Thumb-2</strong>：16 位和 32 位<strong>混合编码</strong>——简单指令用 16 位省空间，复杂指令用 32 位保功能，密度与性能兼得。<strong>Cortex-M3 起只支持 Thumb-2</strong>，这也是 <a href="/scm-docs/sdoc/basic/overview/126b08c73a222946645cba90.html">CortexM3简介</a> 里&quot;PC 指针步长在 2 和 4 字节之间动态变化&quot;的原因：16 位指令占 2 字节、32 位指令占 4 字节，每执行完一条指令，PC 就按这条指令的长度向前推进。</p><p>对 Cortex-M 的 RISC 特征补一个实例印证 Load/Store 架构：想计算内存里两个变量的和，不能&quot;一条指令搞定&quot;，必须先把它们装进寄存器：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LDR   R0, [R1]      ; 从内存取第一个数到 R0（Load）</span></span>
<span class="line"><span>LDR   R2, [R3]      ; 从内存取第二个数到 R2（Load）</span></span>
<span class="line"><span>ADD   R0, R0, R2    ; 寄存器相加（运算不碰内存）</span></span>
<span class="line"><span>STR   R0, [R4]      ; 结果存回内存（Store）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Cortex-M0 / M3 支持的具体指令列表，见 <a href="/scm-docs/sdoc/basic/overview/126b08c738bc16b5b982661d.html">CortexM0简介</a>；ISA 与 ARM 处理器家族的关系见 <a href="/scm-docs/sdoc/basic/overview/126b08ba0eae364f31526d00.html">ARM体系结构</a>。</p><h3 id="_4-从-c-语句到指令-为什么程序员要懂-isa" tabindex="-1">4. 从 C 语句到指令：为什么程序员要懂 ISA <a class="header-anchor" href="#_4-从-c-语句到指令-为什么程序员要懂-isa" aria-label="Permalink to &quot;4. 从 C 语句到指令：为什么程序员要懂 ISA&quot;">​</a></h3><p>日常写的是 C，编译器负责翻译成指令——那为什么还要懂指令集？三个实际理由：</p><p>（1）<strong>调试看反汇编</strong>：程序跑飞、优化导致&quot;变量看不到&quot;、HardFault 定位现场，都要能读懂反汇编窗口里的 <code>LDR/STR/BX</code>；</p><p>（2）<strong>评估性能</strong>：数一数循环体里的指令条数、识别访存指令（通常比寄存器运算慢），就能粗估一段代码的执行周期，比&quot;感觉快&quot;可靠；</p><p>（3）<strong>理解 C 特性的代价</strong>：<code>volatile</code> 强制每次真实访存（多出 LDR/STR）、函数调用有压栈出栈成本、<code>printf</code> 背后是海量指令——这些&quot;常识&quot;都建立在指令视角上。</p><p>指令集解决了&quot;说什么话&quot;，接下来看&quot;说得多快&quot;——同样的指令序列，不同的执行组织方式，性能可以差好几倍。</p><h2 id="二、-流水线-让每个部件都忙起来" tabindex="-1">二、 流水线：让每个部件都忙起来 <a class="header-anchor" href="#二、-流水线-让每个部件都忙起来" aria-label="Permalink to &quot;二、 流水线：让每个部件都忙起来&quot;">​</a></h2><h3 id="_1-一条指令的五个阶段" tabindex="-1">1. 一条指令的五个阶段 <a class="header-anchor" href="#_1-一条指令的五个阶段" aria-label="Permalink to &quot;1. 一条指令的五个阶段&quot;">​</a></h3><p><a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 把指令执行概括为&quot;取指-分析-执行&quot;三步，现代 CPU 把它细化成五个阶段：</p><table tabindex="0"><thead><tr><th>阶段</th><th>缩写</th><th>做什么</th><th>用到的部件</th></tr></thead><tbody><tr><td>取指</td><td>IF</td><td>按 PC 从存储器取出指令</td><td>PC、总线、存储器</td></tr><tr><td>译码</td><td>ID</td><td>分析操作码和操作数</td><td>译码器、寄存器堆读口</td></tr><tr><td>执行</td><td>EX</td><td>完成运算/计算地址</td><td>ALU</td></tr><tr><td>访存</td><td>MEM</td><td>读写数据存储器（仅 Load/Store 指令）</td><td>总线、存储器</td></tr><tr><td>写回</td><td>WB</td><td>结果写回寄存器</td><td>寄存器堆写口</td></tr></tbody></table><p>问题出现在执行方式上。最朴素的<strong>串行执行</strong>：一条指令走完五个阶段，下一条才开始——每个时钟周期里，五个部件只有一个在干活，其余四个闲置。执行 N 条指令需要 5N 个周期，部件利用率只有 20%。</p><h3 id="_2-装配线思维-五段流水线" tabindex="-1">2. 装配线思维：五段流水线 <a class="header-anchor" href="#_2-装配线思维-五段流水线" aria-label="Permalink to &quot;2. 装配线思维：五段流水线&quot;">​</a></h3><p>流水线的想法与工厂装配线一模一样：<strong>不等一件产品走完整条线再上第二件，而是每个工位完成手头工序后立刻接下一件</strong>。指令也一样——第 1 条指令进入译码时，第 2 条就开始取指：</p><table tabindex="0"><thead><tr><th>指令 \\ 周期</th><th>1</th><th>2</th><th>3</th><th>4</th><th>5</th><th>6</th><th>7</th><th>8</th><th>9</th></tr></thead><tbody><tr><td>指令 1</td><td>IF</td><td>ID</td><td>EX</td><td>MEM</td><td>WB</td><td></td><td></td><td></td><td></td></tr><tr><td>指令 2</td><td></td><td>IF</td><td>ID</td><td>EX</td><td>MEM</td><td>WB</td><td></td><td></td><td></td></tr><tr><td>指令 3</td><td></td><td></td><td>IF</td><td>ID</td><td>EX</td><td>MEM</td><td>WB</td><td></td><td></td></tr><tr><td>指令 4</td><td></td><td></td><td></td><td>IF</td><td>ID</td><td>EX</td><td>MEM</td><td>WB</td><td></td></tr><tr><td>指令 5</td><td></td><td></td><td></td><td></td><td>IF</td><td>ID</td><td>EX</td><td>MEM</td><td>WB</td></tr></tbody></table><p>五个阶段如五道工序错开推进：第 5 周期起<strong>每个周期都有一条指令完成</strong>。5 条指令从串行的 25 个周期缩短到 9 个（5 + 5 - 1）；指令越多，加速比越接近级数 5 倍。</p><p>【<strong>注意</strong>】</p><p>流水线提升的是<strong>吞吐量</strong>（单位时间完成的指令数），不是单条指令的延迟——每条指令依然要走完五个阶段、花五个周期，就像快速公交道上车流更密，但每辆车通过全程的时间没变。评估 CPU 性能时（<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 的 MIPS），起作用的正是吞吐量。</p><h3 id="_3-流水线上的三类障碍-冒险" tabindex="-1">3. 流水线上的三类障碍（冒险） <a class="header-anchor" href="#_3-流水线上的三类障碍-冒险" aria-label="Permalink to &quot;3. 流水线上的三类障碍（冒险）&quot;">​</a></h3><p>理想流水线&quot;每拍完成一条&quot;并不总能成立，破坏它的情形统称<strong>冒险</strong>（Hazard），分三类：</p><p>（1）<strong>结构冒险——两条指令抢同一个部件</strong>。典型如取指和访存同时要用同一个存储器端口：第 i 条在访存阶段读数据时，第 i+3 条正要取指，撞车。解法你已经见过——<strong>哈佛结构</strong>：指令和数据分开存储、各有独立总线（<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68ae1e86fc6cd55b.html">LV001</a> 的对比图、<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68b005d840305a2c.html">LV013</a> 的 I-Code/D-Code 总线），取指与访存各走各路，互不相抢——原来哈佛结构不只是存储分工，更是流水线的&quot;配套设施&quot;；</p><p>（2）<strong>数据冒险——后一条指令要用前一条还没写回的结果</strong>。例如 <code>ADD R0,R1,R2</code> 之后紧跟 <code>SUB R3,R0,R4</code>：SUB 取 R0 时，ADD 的结果还没走到写回阶段。经典解法是<strong>前递/旁路</strong>（Forwarding）：ALU 算出的结果不等你回，直接抄近道送给下一级的 ALU 输入；实在救不了的（如 Load 之后立刻用）由编译器或硬件插入等待；</p><p>（3）<strong>控制冒险——分支跳转让已取进的指令作废</strong>。遇到跳转指令时，PC 要等执行阶段才知道去哪，后面已经按顺序取进流水线的指令全是废的，只能<strong>冲刷</strong>（Flush）重来。解法是<strong>分支预测</strong>（猜方向，猜对零代价、猜错冲刷）和编译器把大概率路径安排在顺序流上。在 Cortex-M 上，一次跳转的典型代价是 2～3 个周期——这就是&quot;紧凑循环并非越紧越好&quot;的硬件根源。</p><h3 id="_4-深还是浅-流水线级数的取舍" tabindex="-1">4. 深还是浅：流水线级数的取舍 <a class="header-anchor" href="#_4-深还是浅-流水线级数的取舍" aria-label="Permalink to &quot;4. 深还是浅：流水线级数的取舍&quot;">​</a></h3><p>既然 k 级流水线理想加速比约 k 倍，为什么不做 50 级？因为每一级之间的流水寄存器都给冒险&quot;记账&quot;：级数越深，预测错误的冲刷代价越大、数据前递的路径越长、功耗也越高——NetBurst 架构的 Pentium 4 曾把流水线拉到 31 级冲 4 GHz 主频，最终因能效失控被放弃，是教科书级的教训。</p><p>两端的取舍一目了然：</p><table tabindex="0"><thead><tr><th></th><th>深流水线（PC 的 CPU）</th><th>浅流水线（Cortex-M）</th></tr></thead><tbody><tr><td>典型级数</td><td>十几到二十级以上</td><td>M0/M3：3 级（取指-译码-执行）；M0+：2 级</td></tr><tr><td>追求</td><td>高主频、高吞吐</td><td>低功耗、确定性</td></tr><tr><td>冒险代价</td><td>分支预测失误惩罚重</td><td>冲刷代价小，中断进出快</td></tr><tr><td>适配场景</td><td>通用计算，跑 OS 和应用</td><td>实时控制（<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68af2b7b388addac.html">LV010</a> 的确定性需求）</td></tr></tbody></table><p>Cortex-M3 的三级流水线在 72 MHz 下，多数指令单周期完成，理想吞吐约 72 MIPS——数字不大，但对&quot;控制&quot;够用，而且<strong>中断响应时间恒定</strong>（12 周期入中断），这比峰值性能更符合 MCU 的使命。</p><h3 id="_5-流水线视角对写代码的启示" tabindex="-1">5. 流水线视角对写代码的启示 <a class="header-anchor" href="#_5-流水线视角对写代码的启示" aria-label="Permalink to &quot;5. 流水线视角对写代码的启示&quot;">​</a></h3><p>（1）<strong>分支不是免费的</strong>：<code>if</code> 密集的最内层循环，每次跳转都是 2～3 周期的冲刷代价；条件执行、查表代替分支，都是换性能的思路；</p><p>（2）<strong>中断进出有成本</strong>：进中断要保存现场、冲刷流水线，出中断要恢复——频繁的短中断会吃掉不少周期。Cortex-M 的尾链技术（一个 ISR 直接接下一个 ISR，省去出栈再入栈）就是为此优化，详见中断章节；</p><p>（3）<strong>性能问题用周期数说话</strong>：估算循环耗时 = 指令数 × 每指令周期数 ÷ 主频，配合 Keil 的周期仿真器验证，不靠感觉。</p><h2 id="三、-小结" tabindex="-1">三、 小结 <a class="header-anchor" href="#三、-小结" aria-label="Permalink to &quot;三、 小结&quot;">​</a></h2><ul><li><strong>指令集（ISA）是软硬件的契约</strong>：规定指令、寄存器、寻址与异常模型；CISC 压缩代码、RISC 面向流水线，如今两条路线互相融合；ARM 属 RISC 阵营，Cortex-M 采用 Thumb-2 混合编码兼得密度与性能；</li><li><strong>流水线用&quot;错开重叠&quot;换吞吐量</strong>：五段模型（IF-ID-EX-MEM-WB）理想加速比约等于级数，但单条指令延迟不变；</li><li><strong>三类冒险</strong>各有解药：结构冒险靠哈佛结构、数据冒险靠前递、控制冒险靠分支预测——哈佛结构与流水线的关系在此闭环；</li><li><strong>MCU 选浅流水线</strong>（M3 三级）：低功耗、中断延迟确定，符合&quot;控制优先&quot;的定位。</li></ul><p>指令的执行始终围绕<strong>寄存器</strong>展开——它是流水线各阶段的&quot;工作台&quot;，也是程序员唯一能直接指挥的内核部件。下一篇就把它讲透：<a href="/scm-docs/sdoc/basic/computer-and-mcu/126d62aa68b01ec0b1738d7e.html">LV016-寄存器与硬件控制</a>。</p><h2 id="四、-参考资料" tabindex="-1">四、 参考资料 <a class="header-anchor" href="#四、-参考资料" aria-label="Permalink to &quot;四、 参考资料&quot;">​</a></h2><ul><li>唐朔飞《计算机组成原理（第 3 版）》第 7 章（指令系统）、第 8 章（CPU 的结构与功能）</li><li><a href="/scm-docs/sdoc/basic/overview/126b08ba0eae364f31526d00.html">01-概述/LV001-ARM体系结构</a>——指令集概念与 CISC/RISC 分类</li><li><a href="/scm-docs/sdoc/basic/overview/126b08c738bc16b5b982661d.html">01-概述/LV020-CortexM0简介</a> / <a href="/scm-docs/sdoc/basic/overview/126b08c73a222946645cba90.html">01-概述/LV030-CortexM3简介</a>——具体指令集与内核细节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,63)])])}const b=d(e,[["render",s]]);export{p as __pageData,b as default};
